        const Type elem_type = type_of<num_t>();
        int vec_width = target.natural_vector_size(elem_type);
        if (vec_width < 1) vec_width = 1;

        Var xo("xo"), yo("yo"), xi("xi"), yi("yi");

        // Tile sizes are chosen heuristically; 64x32 works well on
        // typical x86 CPUs while handling non-multiple sizes correctly.
        const int tile_x = 64;
        const int tile_y = 32;

        jacobi
            .tile(x, y, xo, yo, xi, yi, tile_x, tile_y)
            .vectorize(xi, vec_width)
            .parallel(yo);
        // Loop nesting after tile:
        // for yo (parallel):
        //   for xo:
        //     for yi:
        //       for xi (vectorized):
        //         jacobi(x, y) = ...
