    // -------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    // Original C kernel:
    //
    // for (t = 0; t < tsteps; t++) {
    //   // B from A
    //   for (i = 1; i < n-1; i++)
    //     for (j = 1; j < n-1; j++)
