    // good CPU utilization and memory bandwidth.
    Target init_target = get_host_target();
    const int vec_width = init_target.natural_vector_size(type_of<num_t>());

    init_A
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    init_B
        .compute_root()
        .parallel(i)
        .vectorize(j, vec_width);

    // Realize directly into the provided buffers.
    init_A.realize(A);
    init_B.realize(B);
}

int main(int argc, char *argv[]) {
