    // next(x,y) = 0.2 * (cur(x,y) +
    //                    cur(x-1,y) + cur(x+1,y) +
    //                    cur(x,y+1) + cur(x,y-1));
    Func jacobi("jacobi");
    jacobi(x, y) = w * (cur_param(x, y) +
                        cur_param(x - 1, y) +
                        cur_param(x + 1, y) +
                        cur_param(x, y + 1) +
                        cur_param(x, y - 1));

