                // Recall A(i,j) in C is A(j,i) in Halide.
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds to stdout, with microsecond precision.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
